const CACHE_NAME="apex-cache-v2",urlsToCache=["/","/shorts","/predictions","/clips","/navbar.html","/footer.html","/header.html","/header.json","/videos.json","/css/styles.min.css","/js/custom.min.js","/img/logo.png","/img/header.jpg","/img/predictions-logo.png","/img/clips-logo.png"];self.addEventListener("install",a=>{a.waitUntil(caches.open(CACHE_NAME).then(a=>a.addAll(urlsToCache)))}),self.addEventListener("fetch",a=>{a.respondWith(caches.match(a.request).then(b=>{const c=fetch(a.request).then(b=>(caches.open(CACHE_NAME).then(c=>{"GET"===a.request.method&&200===b.status&&c.put(a.request,b.clone())}),b)).catch(()=>{console.log("Network fetch failed, serving from cache if available.")});return b||c}))}),self.addEventListener("activate",a=>{a.waitUntil(caches.keys().then(a=>Promise.all(a.map(a=>{if(a!==CACHE_NAME)return caches.delete(a)}))))});